180→		if (msg.role === "assistant") {
181→			for (const part of msg.content) {
182→				if (part.type === "text") items.push({ type: "text", text: part.text });
183→				else if (part.type === "toolCall") items.push({ type: "toolCall", name: part.name, args: part.arguments });
184→			}
185→		}
186→	}
187→	return items;
188→}
189→
190→async function mapWithConcurrencyLimit<TIn, TOut>(
191→	items: TIn[],
192→	concurrency: number,
193→	fn: (item: TIn, index: number) => Promise<TOut>,
194→): Promise<TOut[]> {
195→	if (items.length === 0) return [];
196→	const limit = Math.max(1, Math.min(concurrency, items.length));
197→	const results: TOut[] = new Array(items.length);
198→	let nextIndex = 0;
199→	const workers = new Array(limit).fill(null).map(async () => {
200→		while (true) {
201→			const current = nextIndex++;
202→			if (current >= items.length) return;
203→			results[current] = await fn(items[current], current);
204→		}
205→	});
206→	await Promise.all(workers);
207→	return results;
208→}
