210→function writePromptToTempFile(agentName: string, prompt: string): { dir: string; filePath: string } {
211→	const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "pi-subagent-"));
212→	const safeName = agentName.replace(/[^\w.-]+/g, "_");
213→	const filePath = path.join(tmpDir, `prompt-${safeName}.md`);
214→	fs.writeFileSync(filePath, prompt, { encoding: "utf-8", mode: 0o600 });
215→	return { dir: tmpDir, filePath };
216→}
