218→type OnUpdateCallback = (partial: AgentToolResult<SubagentDetails>) => void;
219→
220→async function runSingleAgent(
221→	defaultCwd: string,
222→	agents: AgentConfig[],
223→	agentName: string,
224→	task: string,
225→	cwd: string | undefined,
226→	step: number | undefined,
227→	signal: AbortSignal | undefined,
228→	onUpdate: OnUpdateCallback | undefined,
229→	makeDetails: (results: SingleResult[]) => SubagentDetails,
230→): Promise<SingleResult> {
231→	const agent = agents.find((a) => a.name === agentName);
232→
233→	if (!agent) {
234→		const available = agents.map((a) => `"${a.name}"`).join(", ") || "none";
235→		return {
236→			agent: agentName,
237→			agentSource: "unknown",
238→			task,
239→			exitCode: 1,
240→			messages: [],
241→			stderr: `Unknown agent: "${agentName}". Available agents: ${available}.`,
242→			usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
243→			step,
244→		};
245→	}
246→
247→	const args: string[] = ["--mode", "json", "-p", "--no-session"];
248→	if (agent.model) args.push("--model", agent.model);
249→	if (agent.tools && agent.tools.length > 0) args.push("--tools", agent.tools.join(","));
250→
251→	let tmpPromptDir: string | null = null;
252→	let tmpPromptPath: string | null = null;
253→
254→	const currentResult: SingleResult = {
255→		agent: agentName,
256→		agentSource: agent.source,
257→		task,
258→		exitCode: 0,
259→		messages: [],
260→		stderr: "",
261→		usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
262→		model: agent.model,
263→		step,
264→	};
265→
266→	const emitUpdate = () => {
267→		if (onUpdate) {
268→			onUpdate({
269→				content: [{ type: "text", text: getFinalOutput(currentResult.messages) || "(running...)" }],
270→				details: makeDetails([currentResult]),
271→			});
272→		}
273→	};
274→
275→	try {
276→		if (agent.systemPrompt.trim()) {
277→			const tmp = writePromptToTempFile(agent.name, agent.systemPrompt);
278→			tmpPromptDir = tmp.dir;
279→			tmpPromptPath = tmp.filePath;
280→			args.push("--append-system-prompt", tmpPromptPath);
281→		}
282→
283→		args.push(`Task: ${task}`);
284→		let wasAborted = false;
285→
286→		const exitCode = await new Promise<number>((resolve) => {
287→			const proc = spawn("pi", args, { cwd: cwd ?? defaultCwd, shell: false, stdio: ["ignore", "pipe", "pipe"] });
288→			let buffer = "";
289→
290→			const processLine = (line: string) => {
291→				if (!line.trim()) return;
292→				let event: any;
293→				try {
294→					event = JSON.parse(line);
295→				} catch {
296→					return;
297→				}
298→
299→				if (event.type === "message_end" && event.message) {
300→					const msg = event.message as Message;
301→					currentResult.messages.push(msg);
302→
303→					if (msg.role === "assistant") {
304→						currentResult.usage.turns++;
305→						const usage = msg.usage;
306→						if (usage) {
307→							currentResult.usage.input += usage.input || 0;
308→							currentResult.usage.output += usage.output || 0;
309→							currentResult.usage.cacheRead += usage.cacheRead || 0;
310→							currentResult.usage.cacheWrite += usage.cacheWrite || 0;
311→							currentResult.usage.cost += usage.cost?.total || 0;
312→							currentResult.usage.contextTokens = usage.totalTokens || 0;
313→						}
314→						if (!currentResult.model && msg.model) currentResult.model = msg.model;
315→						if (msg.stopReason) currentResult.stopReason = msg.stopReason;
316→						if (msg.errorMessage) currentResult.errorMessage = msg.errorMessage;
317→					}
318→					emitUpdate();
319→				}
320→
321→				if (event.type === "tool_result_end" && event.message) {
322→					currentResult.messages.push(event.message as Message);
323→					emitUpdate();
324→				}
325→			};
326→
327→			proc.stdout.on("data", (data) => {
328→				buffer += data.toString();
329→				const lines = buffer.split("\n");
330→				buffer = lines.pop() || "";
331→				for (const line of lines) processLine(line);
332→			});
333→
334→			proc.stderr.on("data", (data) => {
335→				currentResult.stderr += data.toString();
336→			});
337→
338→			proc.on("close", (code) => {
339→				if (buffer.trim()) processLine(buffer);
340→				resolve(code ?? 0);
341→			});
342→
343→			proc.on("error", () => {
344→				resolve(1);
345→			});
346→
347→			if (signal) {
348→				const killProc = () => {
349→					wasAborted = true;
350→					proc.kill("SIGTERM");
351→					setTimeout(() => {
352→						if (!proc.killed) proc.kill("SIGKILL");
353→					}, 5000);
354→				};
355→				if (signal.aborted) killProc();
356→				else signal.addEventListener("abort", killProc, { once: true });
357→			}
358→		});
359→
360→		currentResult.exitCode = exitCode;
361→		if (wasAborted) throw new Error("Subagent was aborted");
362→		return currentResult;
363→	} finally {
364→		if (tmpPromptPath)
365→			try {
366→				fs.unlinkSync(tmpPromptPath);
367→			} catch {
368→				/* ignore */
369→			}
370→		if (tmpPromptDir)
371→			try {
372→				fs.rmdirSync(tmpPromptDir);
373→			} catch {
374→				/* ignore */
375→			}
376→	}
377→}
378→
379→const TaskItem = Type.Object({
380→	agent: Type.String({ description: "Name of the agent to invoke" }),
381→	task: Type.String({ description: "Task to delegate to the agent" }),
382→	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process" })),
383→});
384→
385→const ChainItem = Type.Object({
386→	agent: Type.String({ description: "Name of the agent to invoke" }),
387→	task: Type.String({ description: "Task with optional {previous} placeholder for prior output" }),
388→	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process" })),
389→});
390→
391→const AgentScopeSchema = StringEnum(["user", "project", "both"] as const, {
392→	description: 'Which agent directories to use. Default: "user". Use "both" to include project-local agents.',
393→	default: "user",
394→});
395→
396→const SubagentParams = Type.Object({
397→	agent: Type.Optional(Type.String({ description: "Name of the agent to invoke (for single mode)" })),
398→	task: Type.Optional(Type.String({ description: "Task to delegate (for single mode)" })),
399→	tasks: Type.Optional(Type.Array(TaskItem, { description: "Array of {agent, task} for parallel execution" })),
400→	chain: Type.Optional(Type.Array(ChainItem, { description: "Array of {agent, task} for sequential execution" })),
401→	agentScope: Type.Optional(AgentScopeSchema),
402→	confirmProjectAgents: Type.Optional(
403→		Type.Boolean({ description: "Prompt before running project-local agents. Default: true.", default: true }),
404→	),
405→	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process (single mode)" })),
406→});
407→
408→export default function (pi: ExtensionAPI) {
409→	pi.registerTool({
410→		name: "subagent",
411→		label: "Subagent",
412→		description: [
413→			"Delegate tasks to specialized subagents with isolated context.",
414→			"Modes: single (agent + task), parallel (tasks array), chain (sequential with {previous} placeholder).",
415→			'Default agent scope is "user" (from ~/.pi/agent/agents).',
416→			'To enable project-local agents in .pi/agents, set agentScope: "both" (or "project").',
417→		].join(" "),
418→		parameters: SubagentParams,
419→
420→		async execute(_toolCallId, params, signal, onUpdate, ctx) {
421→			const agentScope: AgentScope = params.agentScope ?? "user";
422→			const discovery = discoverAgents(ctx.cwd, agentScope);
423→			const agents = discovery.agents;
424→			const confirmProjectAgents = params.confirmProjectAgents ?? true;
425→
426→			const hasChain = (params.chain?.length ?? 0) > 0;
427→			const hasTasks = (params.tasks?.length ?? 0) > 0;
428→			const hasSingle = Boolean(params.agent && params.task);
429→			const modeCount = Number(hasChain) + Number(hasTasks) + Number(hasSingle);
430→
431→			const makeDetails =
432→				(mode: "single" | "parallel" | "chain") =>
433→				(results: SingleResult[]): SubagentDetails => ({
434→					mode,
435→					agentScope,
436→					projectAgentsDir: discovery.projectAgentsDir,
437→					results,
438→				});
439→
440→			if (modeCount !== 1) {
441→				const available = agents.map((a) => `${a.name} (${a.source})`).join(", ") || "none";
442→				return {
443→					content: [
444→						{
445→							type: "text",
446→							text: `Invalid parameters. Provide exactly one mode.\nAvailable agents: ${available}`,
447→						},
448→					],
449→					details: makeDetails("single")([]),
450→				};
451→			}
452→
453→			if ((agentScope === "project" || agentScope === "both") && confirmProjectAgents && ctx.hasUI) {
454→				const requestedAgentNames = new Set<string>();
455→				if (params.chain) for (const step of params.chain) requestedAgentNames.add(step.agent);
456→				if (params.tasks) for (const t of params.tasks) requestedAgentNames.add(t.agent);
457→				if (params.agent) requestedAgentNames.add(params.agent);
458→
459→				const projectAgentsRequested = Array.from(requestedAgentNames)
460→					.map((name) => agents.find((a) => a.name === name))
461→					.filter((a): a is AgentConfig => a?.source === "project");
462→
463→				if (projectAgentsRequested.length > 0) {
464→					const names = projectAgentsRequested.map((a) => a.name).join(", ");
465→					const dir = discovery.projectAgentsDir ?? "(unknown)";
466→					const ok = await ctx.ui.confirm(
467→						"Run project-local agents?",
468→						`Agents: ${names}\nSource: ${dir}\n\nProject agents are repo-controlled. Only continue for trusted repositories.`,
469→					);
470→					if (!ok)
471→						return {
472→							content: [{ type: "text", text: "Canceled: project-local agents not approved." }],
473→							details: makeDetails(hasChain ? "chain" : hasTasks ? "parallel" : "single")([]),
474→						};
475→				}
476→			}
477→
478→			if (params.chain && params.chain.length > 0) {
479→				const results: SingleResult[] = [];
480→				let previousOutput = "";
481→
482→				for (let i = 0; i < params.chain.length; i++) {
483→					const step = params.chain[i];
484→					const taskWithContext = step.task.replace(/\{previous\}/g, previousOutput);
485→
486→					// Create update callback that includes all previous results
487→					const chainUpdate: OnUpdateCallback | undefined = onUpdate
488→						? (partial) => {
489→								// Combine completed results with current streaming result
490→								const currentResult = partial.details?.results[0];
491→								if (currentResult) {
492→									const allResults = [...results, currentResult];
493→									onUpdate({
494→										content: partial.content,
495→										details: makeDetails("chain")(allResults),
496→									});
497→								}
498→							}
499→						: undefined;
500→
501→					const result = await runSingleAgent(
502→						ctx.cwd,
503→						agents,
504→						step.agent,
505→						taskWithContext,
506→						step.cwd,
507→						i + 1,
508→						signal,
509→						chainUpdate,
510→						makeDetails("chain"),
511→					);
512→					results.push(result);
513→
514→					const isError =
515→						result.exitCode !== 0 || result.stopReason === "error" || result.stopReason === "aborted";
516→					if (isError) {
517→						const errorMsg =
518→							result.errorMessage || result.stderr || getFinalOutput(result.messages) || "(no output)";
519→						return {
520→							content: [{ type: "text", text: `Chain stopped at step ${i + 1} (${step.agent}): ${errorMsg}` }],
521→							details: makeDetails("chain")(results),
522→							isError: true,
523→						};
524→					}
525→					previousOutput = getFinalOutput(result.messages);
526→				}
527→				return {
528→					content: [{ type: "text", text: getFinalOutput(results[results.length - 1].messages) || "(no output)" }],
529→					details: makeDetails("chain")(results),
530→				};
531→			}
532→
533→			if (params.tasks && params.tasks.length > 0) {
534→				if (params.tasks.length > MAX_PARALLEL_TASKS)
535→					return {
536→						content: [
537→							{
538→								type: "text",
539→								text: `Too many parallel tasks (${params.tasks.length}). Max is ${MAX_PARALLEL_TASKS}.`,
540→							},
541→						],
542→						details: makeDetails("parallel")([]),
543→					};
544→
545→				// Track all results for streaming updates
546→				const allResults: SingleResult[] = new Array(params.tasks.length);
547→
548→				// Initialize placeholder results
549→				for (let i = 0; i < params.tasks.length; i++) {
550→					allResults[i] = {
551→						agent: params.tasks[i].agent,
552→						agentSource: "unknown",
553→						task: params.tasks[i].task,
554→						exitCode: -1, // -1 = still running
555→						messages: [],
556→						stderr: "",
557→						usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
558→					};
559→				}
560→
561→				const emitParallelUpdate = () => {
562→					if (onUpdate) {
563→						const running = allResults.filter((r) => r.exitCode === -1).length;
564→						const done = allResults.filter((r) => r.exitCode !== -1).length;
565→						onUpdate({
566→							content: [
567→								{ type: "text", text: `Parallel: ${done}/${allResults.length} done, ${running} running...` },
568→							],
569→							details: makeDetails("parallel")([...allResults]),
570→						});
571→					}
572→				};
573→
574→				const results = await mapWithConcurrencyLimit(params.tasks, MAX_CONCURRENCY, async (t, index) => {
575→					const result = await runSingleAgent(
576→						ctx.cwd,
577→						agents,
578→						t.agent,
579→						t.task,
580→						t.cwd,
581→						undefined,
582→						signal,
583→						// Per-task update callback
584→						(partial) => {
585→							if (partial.details?.results[0]) {
586→								allResults[index] = partial.details.results[0];
587→								emitParallelUpdate();
588→							}
589→						},
590→						makeDetails("parallel"),
591→					);
592→					allResults[index] = result;
593→					emitParallelUpdate();
594→					return result;
595→				});
596→
597→				const successCount = results.filter((r) => r.exitCode === 0).length;
598→				const summaries = results.map((r) => {
599→					const output = getFinalOutput(r.messages);
600→					const preview = output.slice(0, 100) + (output.length > 100 ? "..." : "");
601→					return `[${r.agent}] ${r.exitCode === 0 ? "completed" : "failed"}: ${preview || "(no output)"}`;
602→				});
603→				return {
604→					content: [
605→						{
606→							type: "text",
607→							text: `Parallel: ${successCount}/${results.length} succeeded\n\n${summaries.join("\n\n")}`,
608→						},
609→					],
610→					details: makeDetails("parallel")(results),
611→				};
612→			}
613→
614→			if (params.agent && params.task) {
615→				const result = await runSingleAgent(
616→					ctx.cwd,
617→					agents,
618→					params.agent,
619→					params.task,
620→					params.cwd,
621→					undefined,
622→					signal,
623→					onUpdate,
624→					makeDetails("single"),
625→				);
626→				const isError = result.exitCode !== 0 || result.stopReason === "error" || result.stopReason === "aborted";
627→				if (isError) {
628→					const errorMsg =
629→						result.errorMessage || result.stderr || getFinalOutput(result.messages) || "(no output)";
630→					return {
631→						content: [{ type: "text", text: `Agent ${result.stopReason || "failed"}: ${errorMsg}` }],
632→						details: makeDetails("single")([result]),
633→						isError: true,
634→					};
635→				}
636→				return {
637→					content: [{ type: "text", text: getFinalOutput(result.messages) || "(no output)" }],
638→					details: makeDetails("single")([result]),
639→				};
640→			}
641→
642→			const available = agents.map((a) => `${a.name} (${a.source})`).join(", ") || "none";
643→			return {
644→				content: [{ type: "text", text: `Invalid parameters. Available agents: ${available}` }],
645→				details: makeDetails("single")([]),
646→			};
647→		},
648→
649→		renderCall(args, theme) {
650→			const scope: AgentScope = args.agentScope ?? "user";
651→			if (args.chain && args.chain.length > 0) {
652→				let text =
653→					theme.fg("toolTitle", theme.bold("subagent ")) +
654→					theme.fg("accent", `chain (${args.chain.length} steps)`) +
655→					theme.fg("muted", ` [${scope}]`);
656→				for (let i = 0; i < Math.min(args.chain.length, 3); i++) {
657→					const step = args.chain[i];
658→					// Clean up {previous} placeholder for display
659→					const cleanTask = step.task.replace(/\{previous\}/g, "").trim();
660→					const preview = cleanTask.length > 40 ? `${cleanTask.slice(0, 40)}...` : cleanTask;
661→					text +=
662→						"\n  " +
663→						theme.fg("muted", `${i + 1}.`) +
664→						" " +
665→						theme.fg("accent", step.agent) +
666→						theme.fg("dim", ` ${preview}`);
667→				}
668→				if (args.chain.length > 3) text += `\n  ${theme.fg("muted", `... +${args.chain.length - 3} more`)}`;
669→				return new Text(text, 0, 0);
670→			}
671→			if (args.tasks && args.tasks.length > 0) {
672→				let text =
673→					theme.fg("toolTitle", theme.bold("subagent ")) +
674→					theme.fg("accent", `parallel (${args.tasks.length} tasks)`) +
675→					theme.fg("muted", ` [${scope}]`);
676→				for (const t of args.tasks.slice(0, 3)) {
677→					const preview = t.task.length > 40 ? `${t.task.slice(0, 40)}...` : t.task;
678→					text += `\n  ${theme.fg("accent", t.agent)}${theme.fg("dim", ` ${preview}`)}`;
679→				}
680→				if (args.tasks.length > 3) text += `\n  ${theme.fg("muted", `... +${args.tasks.length - 3} more`)}`;
681→				return new Text(text, 0, 0);
682→			}
683→			const agentName = args.agent || "...";
684→			const preview = args.task ? (args.task.length > 60 ? `${args.task.slice(0, 60)}...` : args.task) : "...";
685→			let text =
686→				theme.fg("toolTitle", theme.bold("subagent ")) +
687→				theme.fg("accent", agentName) +
688→				theme.fg("muted", ` [${scope}]`);
689→			text += `\n  ${theme.fg("dim", preview)}`;
690→			return new Text(text, 0, 0);
691→		},
692→
693→		renderResult(result, { expanded }, theme) {
694→			const details = result.details as SubagentDetails | undefined;
695→			if (!details || details.results.length === 0) {
696→				const text = result.content[0];
697→				return new Text(text?.type === "text" ? text.text : "(no output)", 0, 0);
698→			}
699→
700→			const mdTheme = getMarkdownTheme();
701→
702→			const renderDisplayItems = (items: DisplayItem[], limit?: number) => {
703→				const toShow = limit ? items.slice(-limit) : items;
704→				const skipped = limit && items.length > limit ? items.length - limit : 0;
705→				let text = "";
706→				if (skipped > 0) text += theme.fg("muted", `... ${skipped} earlier items\n`);
707→				for (const item of toShow) {
708→					if (item.type === "text") {
709→						const preview = expanded ? item.text : item.text.split("\n").slice(0, 3).join("\n");
710→						text += `${theme.fg("toolOutput", preview)}\n`;
711→					} else {
712→						text += `${theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme))}\n`;
713→					}
714→				}
715→				return text.trimEnd();
716→			};
717→
718→			if (details.mode === "single" && details.results.length === 1) {
719→				const r = details.results[0];
720→				const isError = r.exitCode !== 0 || r.stopReason === "error" || r.stopReason === "aborted";
721→				const icon = isError ? theme.fg("error", "✗") : theme.fg("success", "✓");
722→				const displayItems = getDisplayItems(r.messages);
723→				const finalOutput = getFinalOutput(r.messages);
724→
725→				if (expanded) {
726→					const container = new Container();
727→					let header = `${icon} ${theme.fg("toolTitle", theme.bold(r.agent))}${theme.fg("muted", ` (${r.agentSource})`)}`;
728→					if (isError && r.stopReason) header += ` ${theme.fg("error", `[${r.stopReason}]`)}`;
729→					container.addChild(new Text(header, 0, 0));
