 31→function formatTokens(count: number): string {
 32→	if (count < 1000) return count.toString();
 33→	if (count < 10000) return `${(count / 1000).toFixed(1)}k`;
 34→	if (count < 1000000) return `${Math.round(count / 1000)}k`;
 35→	return `${(count / 1000000).toFixed(1)}M`;
 36→}
