 38→function formatUsageStats(
 39→	usage: {
 40→		input: number;
 41→		output: number;
 42→		cacheRead: number;
 43→		cacheWrite: number;
 44→		cost: number;
 45→		contextTokens?: number;
 46→		turns?: number;
 47→	},
 48→	model?: string,
 49→): string {
 50→	const parts: string[] = [];
 51→	if (usage.turns) parts.push(`${usage.turns} turn${usage.turns > 1 ? "s" : ""}`);
 52→	if (usage.input) parts.push(`↑${formatTokens(usage.input)}`);
 53→	if (usage.output) parts.push(`↓${formatTokens(usage.output)}`);
 54→	if (usage.cacheRead) parts.push(`R${formatTokens(usage.cacheRead)}`);
 55→	if (usage.cacheWrite) parts.push(`W${formatTokens(usage.cacheWrite)}`);
 56→	if (usage.cost) parts.push(`$${usage.cost.toFixed(4)}`);
 57→	if (usage.contextTokens && usage.contextTokens > 0) {
 58→		parts.push(`ctx:${formatTokens(usage.contextTokens)}`);
 59→	}
 60→	if (model) parts.push(model);
 61→	return parts.join(" ");
 62→}
