 64→function formatToolCall(
 65→	toolName: string,
 66→	args: Record<string, unknown>,
 67→	themeFg: (color: any, text: string) => string,
 68→): string {
 69→	const shortenPath = (p: string) => {
 70→		const home = os.homedir();
 71→		return p.startsWith(home) ? `~${p.slice(home.length)}` : p;
 72→	};
 73→
 74→	switch (toolName) {
 75→		case "bash": {
 76→			const command = (args.command as string) || "...";
 77→			const preview = command.length > 60 ? `${command.slice(0, 60)}...` : command;
 78→			return themeFg("muted", "$ ") + themeFg("toolOutput", preview);
 79→		}
 80→		case "read": {
 81→			const rawPath = (args.file_path || args.path || "...") as string;
 82→			const filePath = shortenPath(rawPath);
 83→			const offset = args.offset as number | undefined;
 84→			const limit = args.limit as number | undefined;
 85→			let text = themeFg("accent", filePath);
 86→			if (offset !== undefined || limit !== undefined) {
 87→				const startLine = offset ?? 1;
 88→				const endLine = limit !== undefined ? startLine + limit - 1 : "";
 89→				text += themeFg("warning", `:${startLine}${endLine ? `-${endLine}` : ""}`);
 90→			}
 91→			return themeFg("muted", "read ") + text;
 92→		}
 93→		case "write": {
 94→			const rawPath = (args.file_path || args.path || "...") as string;
 95→			const filePath = shortenPath(rawPath);
 96→			const content = (args.content || "") as string;
 97→			const lines = content.split("\n").length;
 98→			let text = themeFg("muted", "write ") + themeFg("accent", filePath);
 99→			if (lines > 1) text += themeFg("dim", ` (${lines} lines)`);
100→			return text;
101→		}
102→		case "edit": {
103→			const rawPath = (args.file_path || args.path || "...") as string;
104→			return themeFg("muted", "edit ") + themeFg("accent", shortenPath(rawPath));
105→		}
106→		case "ls": {
107→			const rawPath = (args.path || ".") as string;
108→			return themeFg("muted", "ls ") + themeFg("accent", shortenPath(rawPath));
109→		}
110→		case "find": {
111→			const pattern = (args.pattern || "*") as string;
112→			const rawPath = (args.path || ".") as string;
113→			return themeFg("muted", "find ") + themeFg("accent", pattern) + themeFg("dim", ` in ${shortenPath(rawPath)}`);
114→		}
115→		case "grep": {
116→			const pattern = (args.pattern || "") as string;
117→			const rawPath = (args.path || ".") as string;
118→			return (
119→				themeFg("muted", "grep ") +
120→				themeFg("accent", `/${pattern}/`) +
121→				themeFg("dim", ` in ${shortenPath(rawPath)}`)
122→			);
123→		}
124→		default: {
125→			const argsStr = JSON.stringify(args);
126→			const preview = argsStr.length > 50 ? `${argsStr.slice(0, 50)}...` : argsStr;
127→			return themeFg("accent", toolName) + themeFg("dim", ` ${preview}`);
128→		}
129→	}
130→}
