163→function getFinalOutput(messages: Message[]): string {
164→	for (let i = messages.length - 1; i >= 0; i--) {
165→		const msg = messages[i];
166→		if (msg.role === "assistant") {
167→			for (const part of msg.content) {
168→				if (part.type === "text") return part.text;
169→			}
170→		}
171→	}
172→	return "";
173→}
