175→type DisplayItem = { type: "text"; text: string } | { type: "toolCall"; name: string; args: Record<string, any> };
176→
177→function getDisplayItems(messages: Message[]): DisplayItem[] {
178→	const items: DisplayItem[] = [];
179→	for (const msg of messages) {
180→		if (msg.role === "assistant") {
181→			for (const part of msg.content) {
182→				if (part.type === "text") items.push({ type: "text", text: part.text });
183→				else if (part.type === "toolCall") items.push({ type: "toolCall", name: part.name, args: part.arguments });
184→			}
185→		}
186→	}
187→	return items;
188→}
