507→						i + 1,
508→						signal,
509→						chainUpdate,
510→						makeDetails("chain"),
511→					);
512→					results.push(result);
513→
514→					const isError =
515→						result.exitCode !== 0 || result.stopReason === "error" || result.stopReason === "aborted";
516→					if (isError) {
517→						const errorMsg =
518→							result.errorMessage || result.stderr || getFinalOutput(result.messages) || "(no output)";
519→						return {
520→							content: [{ type: "text", text: `Chain stopped at step ${i + 1} (${step.agent}): ${errorMsg}` }],
521→							details: makeDetails("chain")(results),
522→							isError: true,
523→						};
524→					}
525→					previousOutput = getFinalOutput(result.messages);
526→				}
527→				return {
528→					content: [{ type: "text", text: getFinalOutput(results[results.length - 1].messages) || "(no output)" }],
529→					details: makeDetails("chain")(results),
530→				};
531→			}
532→
533→			if (params.tasks && params.tasks.length > 0) {
534→				if (params.tasks.length > MAX_PARALLEL_TASKS)
535→					return {
536→						content: [
537→							{
538→								type: "text",
539→								text: `Too many parallel tasks (${params.tasks.length}). Max is ${MAX_PARALLEL_TASKS}.`,
540→							},
541→						],
542→						details: makeDetails("parallel")([]),
543→					};
544→
545→				// Track all results for streaming updates
546→				const allResults: SingleResult[] = new Array(params.tasks.length);
547→
548→				// Initialize placeholder results
549→				for (let i = 0; i < params.tasks.length; i++) {
550→					allResults[i] = {
551→						agent: params.tasks[i].agent,
552→						agentSource: "unknown",
553→						task: params.tasks[i].task,
554→						exitCode: -1, // -1 = still running
555→						messages: [],
556→						stderr: "",
557→						usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
558→					};
559→				}
560→
561→				const emitParallelUpdate = () => {
562→					if (onUpdate) {
563→						const running = allResults.filter((r) => r.exitCode === -1).length;
564→						const done = allResults.filter((r) => r.exitCode !== -1).length;
565→						onUpdate({
566→							content: [
567→								{ type: "text", text: `Parallel: ${done}/${allResults.length} done, ${running} running...` },
568→							],
569→							details: makeDetails("parallel")([...allResults]),
570→						});
571→					}
572→				};
573→
574→				const results = await mapWithConcurrencyLimit(params.tasks, MAX_CONCURRENCY, async (t, index) => {
575→					const result = await runSingleAgent(
576→						ctx.cwd,
577→						agents,
578→						t.agent,
579→						t.task,
580→						t.cwd,
581→						undefined,
582→						signal,
583→						// Per-task update callback
584→						(partial) => {
585→							if (partial.details?.results[0]) {
586→								allResults[index] = partial.details.results[0];
587→								emitParallelUpdate();
588→							}
589→						},
590→						makeDetails("parallel"),
591→					);
592→					allResults[index] = result;
593→					emitParallelUpdate();
594→					return result;
595→				});
596→
597→				const successCount = results.filter((r) => r.exitCode === 0).length;
598→				const summaries = results.map((r) => {
599→					const output = getFinalOutput(r.messages);
600→					const preview = output.slice(0, 100) + (output.length > 100 ? "..." : "");
601→					return `[${r.agent}] ${r.exitCode === 0 ? "completed" : "failed"}: ${preview || "(no output)"}`;
602→				});
603→				return {
604→					content: [
605→						{
606→							type: "text",
607→							text: `Parallel: ${successCount}/${results.length} succeeded\n\n${summaries.join("\n\n")}`,
608→						},
609→					],
610→					details: makeDetails("parallel")(results),
611→				};
612→			}
613→
614→			if (params.agent && params.task) {
615→				const result = await runSingleAgent(
616→					ctx.cwd,
617→					agents,
618→					params.agent,
619→					params.task,
620→					params.cwd,
621→					undefined,
622→					signal,
623→					onUpdate,
624→					makeDetails("single"),
625→				);
626→				const isError = result.exitCode !== 0 || result.stopReason === "error" || result.stopReason === "aborted";
627→				if (isError) {
628→					const errorMsg =
629→						result.errorMessage || result.stderr || getFinalOutput(result.messages) || "(no output)";
630→					return {
631→						content: [{ type: "text", text: `Agent ${result.stopReason || "failed"}: ${errorMsg}` }],
632→						details: makeDetails("single")([result]),
633→						isError: true,
634→					};
635→				}
636→				return {
637→					content: [{ type: "text", text: getFinalOutput(result.messages) || "(no output)" }],
638→					details: makeDetails("single")([result]),
639→				};
640→			}
641→
642→			const available = agents.map((a) => `${a.name} (${a.source})`).join(", ") || "none";
643→			return {
644→				content: [{ type: "text", text: `Invalid parameters. Available agents: ${available}` }],
645→				details: makeDetails("single")([]),
646→			};
647→		},
648→
649→		renderCall(args, theme) {
650→			const scope: AgentScope = args.agentScope ?? "user";
651→			if (args.chain && args.chain.length > 0) {
652→				let text =
653→					theme.fg("toolTitle", theme.bold("subagent ")) +
654→					theme.fg("accent", `chain (${args.chain.length} steps)`) +
655→					theme.fg("muted", ` [${scope}]`);
656→				for (let i = 0; i < Math.min(args.chain.length, 3); i++) {
657→					const step = args.chain[i];
658→					// Clean up {previous} placeholder for display
659→					const cleanTask = step.task.replace(/\{previous\}/g, "").trim();
660→					const preview = cleanTask.length > 40 ? `${cleanTask.slice(0, 40)}...` : cleanTask;
661→					text +=
662→						"\n  " +
663→						theme.fg("muted", `${i + 1}.`) +
664→						" " +
665→						theme.fg("accent", step.agent) +
666→						theme.fg("dim", ` ${preview}`);
667→				}
668→				if (args.chain.length > 3) text += `\n  ${theme.fg("muted", `... +${args.chain.length - 3} more`)}`;
669→				return new Text(text, 0, 0);
670→			}
671→			if (args.tasks && args.tasks.length > 0) {
672→				let text =
673→					theme.fg("toolTitle", theme.bold("subagent ")) +
674→					theme.fg("accent", `parallel (${args.tasks.length} tasks)`) +
675→					theme.fg("muted", ` [${scope}]`);
676→				for (const t of args.tasks.slice(0, 3)) {
677→					const preview = t.task.length > 40 ? `${t.task.slice(0, 40)}...` : t.task;
678→					text += `\n  ${theme.fg("accent", t.agent)}${theme.fg("dim", ` ${preview}`)}`;
679→				}
680→				if (args.tasks.length > 3) text += `\n  ${theme.fg("muted", `... +${args.tasks.length - 3} more`)}`;
681→				return new Text(text, 0, 0);
682→			}
683→			const agentName = args.agent || "...";
684→			const preview = args.task ? (args.task.length > 60 ? `${args.task.slice(0, 60)}...` : args.task) : "...";
685→			let text =
686→				theme.fg("toolTitle", theme.bold("subagent ")) +
687→				theme.fg("accent", agentName) +
688→				theme.fg("muted", ` [${scope}]`);
689→			text += `\n  ${theme.fg("dim", preview)}`;
690→			return new Text(text, 0, 0);
691→		},
692→
693→		renderResult(result, { expanded }, theme) {
694→			const details = result.details as SubagentDetails | undefined;
695→			if (!details || details.results.length === 0) {
696→				const text = result.content[0];
697→				return new Text(text?.type === "text" ? text.text : "(no output)", 0, 0);
698→			}
699→
700→			const mdTheme = getMarkdownTheme();
701→
702→			const renderDisplayItems = (items: DisplayItem[], limit?: number) => {
703→				const toShow = limit ? items.slice(-limit) : items;
704→				const skipped = limit && items.length > limit ? items.length - limit : 0;
705→				let text = "";
706→				if (skipped > 0) text += theme.fg("muted", `... ${skipped} earlier items\n`);
707→				for (const item of toShow) {
708→					if (item.type === "text") {
709→						const preview = expanded ? item.text : item.text.split("\n").slice(0, 3).join("\n");
710→						text += `${theme.fg("toolOutput", preview)}\n`;
711→					} else {
712→						text += `${theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme))}\n`;
713→					}
714→				}
715→				return text.trimEnd();
716→			};
717→
718→			if (details.mode === "single" && details.results.length === 1) {
719→				const r = details.results[0];
720→				const isError = r.exitCode !== 0 || r.stopReason === "error" || r.stopReason === "aborted";
721→				const icon = isError ? theme.fg("error", "✗") : theme.fg("success", "✓");
722→				const displayItems = getDisplayItems(r.messages);
723→				const finalOutput = getFinalOutput(r.messages);
724→
725→				if (expanded) {
726→					const container = new Container();
727→					let header = `${icon} ${theme.fg("toolTitle", theme.bold(r.agent))}${theme.fg("muted", ` (${r.agentSource})`)}`;
728→					if (isError && r.stopReason) header += ` ${theme.fg("error", `[${r.stopReason}]`)}`;
729→					container.addChild(new Text(header, 0, 0));
730→					if (isError && r.errorMessage)
731→						container.addChild(new Text(theme.fg("error", `Error: ${r.errorMessage}`), 0, 0));
732→					container.addChild(new Spacer(1));
733→					container.addChild(new Text(theme.fg("muted", "─── Task ───"), 0, 0));
734→					container.addChild(new Text(theme.fg("dim", r.task), 0, 0));
735→					container.addChild(new Spacer(1));
736→					container.addChild(new Text(theme.fg("muted", "─── Output ───"), 0, 0));
737→					if (displayItems.length === 0 && !finalOutput) {
738→						container.addChild(new Text(theme.fg("muted", "(no output)"), 0, 0));
739→					} else {
740→						for (const item of displayItems) {
741→							if (item.type === "toolCall")
742→								container.addChild(
743→									new Text(
744→										theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme)),
745→										0,
746→										0,
747→									),
748→								);
749→						}
750→						if (finalOutput) {
751→							container.addChild(new Spacer(1));
752→							container.addChild(new Markdown(finalOutput.trim(), 0, 0, mdTheme));
753→						}
754→					}
755→					const usageStr = formatUsageStats(r.usage, r.model);
756→					if (usageStr) {
757→						container.addChild(new Spacer(1));
758→						container.addChild(new Text(theme.fg("dim", usageStr), 0, 0));
759→					}
760→					return container;
761→				}
762→
763→				let text = `${icon} ${theme.fg("toolTitle", theme.bold(r.agent))}${theme.fg("muted", ` (${r.agentSource})`)}`;
764→				if (isError && r.stopReason) text += ` ${theme.fg("error", `[${r.stopReason}]`)}`;
765→				if (isError && r.errorMessage) text += `\n${theme.fg("error", `Error: ${r.errorMessage}`)}`;
766→				else if (displayItems.length === 0) text += `\n${theme.fg("muted", "(no output)")}`;
767→				else {
768→					text += `\n${renderDisplayItems(displayItems, COLLAPSED_ITEM_COUNT)}`;
769→					if (displayItems.length > COLLAPSED_ITEM_COUNT) text += `\n${theme.fg("muted", "(Ctrl+O to expand)")}`;
770→				}
771→				const usageStr = formatUsageStats(r.usage, r.model);
772→				if (usageStr) text += `\n${theme.fg("dim", usageStr)}`;
773→				return new Text(text, 0, 0);
774→			}
775→
776→			const aggregateUsage = (results: SingleResult[]) => {
777→				const total = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, turns: 0 };
778→				for (const r of results) {
779→					total.input += r.usage.input;
780→					total.output += r.usage.output;
781→					total.cacheRead += r.usage.cacheRead;
782→					total.cacheWrite += r.usage.cacheWrite;
783→					total.cost += r.usage.cost;
784→					total.turns += r.usage.turns;
785→				}
786→				return total;
787→			};
788→
789→			if (details.mode === "chain") {
790→				const successCount = details.results.filter((r) => r.exitCode === 0).length;
791→				const icon = successCount === details.results.length ? theme.fg("success", "✓") : theme.fg("error", "✗");
792→
793→				if (expanded) {
794→					const container = new Container();
795→					container.addChild(
796→						new Text(
797→							icon +
798→								" " +
799→								theme.fg("toolTitle", theme.bold("chain ")) +
800→								theme.fg("accent", `${successCount}/${details.results.length} steps`),
801→							0,
802→							0,
803→						),
804→					);
805→
806→					for (const r of details.results) {
807→						const rIcon = r.exitCode === 0 ? theme.fg("success", "✓") : theme.fg("error", "✗");
808→						const displayItems = getDisplayItems(r.messages);
809→						const finalOutput = getFinalOutput(r.messages);
810→
811→						container.addChild(new Spacer(1));
812→						container.addChild(
813→							new Text(
814→								`${theme.fg("muted", `─── Step ${r.step}: `) + theme.fg("accent", r.agent)} ${rIcon}`,
815→								0,
816→								0,
817→							),
818→						);
819→						container.addChild(new Text(theme.fg("muted", "Task: ") + theme.fg("dim", r.task), 0, 0));
820→
821→						// Show tool calls
822→						for (const item of displayItems) {
823→							if (item.type === "toolCall") {
824→								container.addChild(
825→									new Text(
826→										theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme)),
827→										0,
828→										0,
829→									),
830→								);
831→							}
832→						}
833→
834→						// Show final output as markdown
835→						if (finalOutput) {
836→							container.addChild(new Spacer(1));
837→							container.addChild(new Markdown(finalOutput.trim(), 0, 0, mdTheme));
838→						}
839→
840→						const stepUsage = formatUsageStats(r.usage, r.model);
841→						if (stepUsage) container.addChild(new Text(theme.fg("dim", stepUsage), 0, 0));
842→					}
843→
844→					const usageStr = formatUsageStats(aggregateUsage(details.results));
845→					if (usageStr) {
846→						container.addChild(new Spacer(1));
847→						container.addChild(new Text(theme.fg("dim", `Total: ${usageStr}`), 0, 0));
848→					}
849→					return container;
850→				}
851→
852→				// Collapsed view
853→				let text =
854→					icon +
855→					" " +
856→					theme.fg("toolTitle", theme.bold("chain ")) +
857→					theme.fg("accent", `${successCount}/${details.results.length} steps`);
858→				for (const r of details.results) {
859→					const rIcon = r.exitCode === 0 ? theme.fg("success", "✓") : theme.fg("error", "✗");
860→					const displayItems = getDisplayItems(r.messages);
861→					text += `\n\n${theme.fg("muted", `─── Step ${r.step}: `)}${theme.fg("accent", r.agent)} ${rIcon}`;
862→					if (displayItems.length === 0) text += `\n${theme.fg("muted", "(no output)")}`;
863→					else text += `\n${renderDisplayItems(displayItems, 5)}`;
864→				}
865→				const usageStr = formatUsageStats(aggregateUsage(details.results));
866→				if (usageStr) text += `\n\n${theme.fg("dim", `Total: ${usageStr}`)}`;
867→				text += `\n${theme.fg("muted", "(Ctrl+O to expand)")}`;
868→				return new Text(text, 0, 0);
869→			}
870→
871→			if (details.mode === "parallel") {
872→				const running = details.results.filter((r) => r.exitCode === -1).length;
873→				const successCount = details.results.filter((r) => r.exitCode === 0).length;
874→				const failCount = details.results.filter((r) => r.exitCode > 0).length;
875→				const isRunning = running > 0;
876→				const icon = isRunning
877→					? theme.fg("warning", "⏳")
878→					: failCount > 0
879→						? theme.fg("warning", "◐")
880→						: theme.fg("success", "✓");
881→				const status = isRunning
882→					? `${successCount + failCount}/${details.results.length} done, ${running} running`
883→					: `${successCount}/${details.results.length} tasks`;
884→
885→				if (expanded && !isRunning) {
886→					const container = new Container();
887→					container.addChild(
888→						new Text(
889→							`${icon} ${theme.fg("toolTitle", theme.bold("parallel "))}${theme.fg("accent", status)}`,
890→							0,
891→							0,
892→						),
893→					);
894→
895→					for (const r of details.results) {
896→						const rIcon = r.exitCode === 0 ? theme.fg("success", "✓") : theme.fg("error", "✗");
897→						const displayItems = getDisplayItems(r.messages);
898→						const finalOutput = getFinalOutput(r.messages);
899→
900→						container.addChild(new Spacer(1));
901→						container.addChild(
902→							new Text(`${theme.fg("muted", "─── ") + theme.fg("accent", r.agent)} ${rIcon}`, 0, 0),
903→						);
904→						container.addChild(new Text(theme.fg("muted", "Task: ") + theme.fg("dim", r.task), 0, 0));
905→
906→						// Show tool calls
907→						for (const item of displayItems) {
908→							if (item.type === "toolCall") {
909→								container.addChild(
910→									new Text(
911→										theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme)),
912→										0,
913→										0,
914→									),
915→								);
916→							}
917→						}
918→
919→						// Show final output as markdown
920→						if (finalOutput) {
921→							container.addChild(new Spacer(1));
922→							container.addChild(new Markdown(finalOutput.trim(), 0, 0, mdTheme));
923→						}
924→
925→						const taskUsage = formatUsageStats(r.usage, r.model);
926→						if (taskUsage) container.addChild(new Text(theme.fg("dim", taskUsage), 0, 0));
927→					}
928→
929→					const usageStr = formatUsageStats(aggregateUsage(details.results));
930→					if (usageStr) {
931→						container.addChild(new Spacer(1));
932→						container.addChild(new Text(theme.fg("dim", `Total: ${usageStr}`), 0, 0));
933→					}
934→					return container;
935→				}
936→
937→				// Collapsed view (or still running)
938→				let text = `${icon} ${theme.fg("toolTitle", theme.bold("parallel "))}${theme.fg("accent", status)}`;
939→				for (const r of details.results) {
940→					const rIcon =
941→						r.exitCode === -1
942→							? theme.fg("warning", "⏳")
943→							: r.exitCode === 0
944→								? theme.fg("success", "✓")
945→								: theme.fg("error", "✗");
946→					const displayItems = getDisplayItems(r.messages);
947→					text += `\n\n${theme.fg("muted", "─── ")}${theme.fg("accent", r.agent)} ${rIcon}`;
948→					if (displayItems.length === 0)
949→						text += `\n${theme.fg("muted", r.exitCode === -1 ? "(running...)" : "(no output)")}`;
950→					else text += `\n${renderDisplayItems(displayItems, 5)}`;
951→				}
952→				if (!isRunning) {
953→					const usageStr = formatUsageStats(aggregateUsage(details.results));
954→					if (usageStr) text += `\n\n${theme.fg("dim", `Total: ${usageStr}`)}`;
955→				}
956→				if (!expanded) text += `\n${theme.fg("muted", "(Ctrl+O to expand)")}`;
957→				return new Text(text, 0, 0);
958→			}
959→
960→			const text = result.content[0];
961→			return new Text(text?.type === "text" ? text.text : "(no output)", 0, 0);
962→		},
963→	});
964→}
